arguments.command:
cat > /tmp/askpass.sh <<'EOS'
#!/bin/sh
case "$1" in
  *Username*) echo "x-access-token" ;;
  *Password*) printf '%s' "$GITHUB_TOKEN" ;;
  *) echo "" ;;
esac
EOS
chmod 700 /tmp/askpass.sh
GIT_ASKPASS=/tmp/askpass.sh git -C /tmp/rachel-work push origin friend/rachel 2>&1 | tail -5
